glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
#if USE_LOCAL
  layout(std140) uniform CCLocal {
    highp mat4 cc_matWorld;
    highp mat4 cc_matWorldIT;
    highp vec4 cc_lightingMapUVParam;
    highp vec4 cc_localShadowBias;
    highp vec4 cc_reflectionProbeData1;
    highp vec4 cc_reflectionProbeData2;
    highp vec4 cc_reflectionProbeBlendData1;
    highp vec4 cc_reflectionProbeBlendData2;
  };
#endif
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec4 color;
out vec2 uv0;
vec4 vert () {
  vec4 p = vec4(a_position, 1.0);
  #if USE_LOCAL
    p = cc_matWorld * p;
  #endif
  uv0 = a_texCoord;
  color = a_color;
  return cc_matViewProj * p;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
#if USE_ALPHA_TEST
  layout(std140) uniform ALPHA_TEST_DATA {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
    if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
    if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 color;
in vec2 uv0;
layout(std140) uniform Death {
  vec4 deathState;
  vec4 deathRect;
  vec4 deathShape;
  vec4 deathStyle;
  vec4 deathMotion;
};
uniform sampler2D cc_spriteTexture;
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}
vec4 frag () {
  vec2 local = clamp((uv0 - deathRect.xy) / deathRect.zw, 0.0, 1.0);
  vec2 p = (local - 0.5) * (deathShape.xy + deathShape.zw * 2.0);
  float t = max(0.0, deathState.x);
  float progress = clamp(deathState.y, 0.0, 1.0);
  float open = smoothstep(0.0, 0.055, t);
  vec4 result = vec4(0.0);
  for (int i = 0; i < 6; i++) {
    float id = float(i);
    float col = mod(id, 2.0), row = floor(id / 2.0);
    vec2 center = (vec2((col + 0.5) * 0.5, (row + 0.5) / 3.0) - 0.5) * deathShape.xy;
    float n = hash(vec2(id + 1.0, deathState.z));
    float n2 = hash(vec2(deathState.z, id + 7.0));
    vec2 radial = normalize(center / deathShape.xy + vec2(0.001));
    float kick = 1.0 - exp(-t * 32.0);
    vec2 travel = radial * (9.0 + n * 5.0) * kick * deathState.w;
    travel += deathMotion.xy * (6.0 + n2 * 3.0) * kick * deathState.w;
    travel += vec2(radial.x * 16.0, 18.0 + n2 * 24.0) * t;
    travel.y -= 180.0 * t * t;
    float angle = (n * 2.0 - 1.0) * (kick * 0.16 + t * 1.8);
    float c = cos(angle), s = sin(angle);
    vec2 relative = p - center - travel;
    vec2 source = vec2(c * relative.x + s * relative.y, -s * relative.x + c * relative.y)
      / (1.0 - smoothstep(0.25, 1.0, progress) * 0.38) + center;
    vec2 q = source / deathShape.xy + 0.5;
    float cutX = 0.5 + 0.065 * sin(q.y * 5.0 + deathState.z);
    float cutA = 0.32 + 0.035 * sin(q.x * 7.0 + deathState.z * 1.3);
    float cutB = 0.68 + 0.035 * sin(q.x * 6.0 + deathState.z * 1.7);
    float side = col < 0.5 ? cutX - q.x : q.x - cutX;
    float band = row < 0.5 ? cutA - q.y : row < 1.5 ? min(q.y - cutA, cutB - q.y) : q.y - cutB;
    float edge = min(side, band);
    float inside = step(0.0, q.x) * step(q.x, 1.0) * step(0.0, q.y) * step(q.y, 1.0);
    float mask = step(0.0, edge) * smoothstep(0.0, 0.008, edge + 0.008 * (1.0 - open)) * inside;
    vec2 sampleUV = deathRect.xy + clamp(q, 0.0, 1.0) * deathRect.zw;
    vec4 piece = CCSampleWithAlphaSeparated(cc_spriteTexture, sampleUV);
    float light = dot(piece.rgb, vec3(0.299, 0.587, 0.114));
    if (deathStyle.a > 2.5) {
      vec3 ice = clamp(light * vec3(0.58, 0.94, 1.16) + vec3(0.02, 0.05, 0.08), 0.0, 1.0);
      piece.rgb = mix(piece.rgb, ice, open * 0.48);
    } else if (deathStyle.a > 0.5 && deathStyle.a < 1.5) {
      piece.rgb = mix(piece.rgb, vec3(light) * vec3(0.55, 0.32, 0.18), progress * 0.5);
    }
    piece.a *= mask * (1.0 - smoothstep(0.23, 1.0, progress));
    result.rgb = piece.rgb * piece.a + result.rgb * (1.0 - piece.a);
    result.a = piece.a + result.a * (1.0 - piece.a);
  }
  result.rgb /= max(result.a, 0.001);
  result.rgb *= color.rgb;
  result.a *= color.a;
  ALPHA_TEST(result);
  return result;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

